fn r_consonant(z: &mut Env) -> i32 {
    if z.in_grouping_b_utf8(G_CONSONANT, 2325, 2399, false) != 0 {
        return 0;
    }
    1
}

pub(super) fn stem(z: &mut Env) -> i32 {
    {
        let ret = z.skip_utf8(z.c, z.l, 1);
        if ret < 0 {
            return 0;
        }
        z.c = ret;
    }
    z.lb = z.c;
    z.c = z.l;
    z.ket = z.c;
    if find_among_b(z, A_0) == 0 {
        return 0;
    }
    z.bra = z.c;
    {
        let ret = z.slice_del();
        if ret < 0 {
            return ret;
        }
    }
    z.c = z.lb;
    1
}
